def newer(e, stored):
    if stored is None:
        return True
    if e.get("version_seq") is not None and stored["version_seq"] is not None:
        return e["version_seq"] > stored["version_seq"]
    # etag-only apps: etags have no order, so use modified_at, then a changed hash
    if e["modified_at"] != stored["modified_at"]:
        return e["modified_at"] > stored["modified_at"]
    return stored["content_hash"] is not None and e["content_hash"] != stored["content_hash"]

def decide(conn, e):
    for k in ("tenant", "doc_id", "version", "content_hash", "modified_at"):
        if k not in e:
            return bump(conn, "invalid")
    t, d = e["tenant"], e["doc_id"]
    # fast path: the exact (doc, version) was seen inside the idempotency window
    seen = conn.execute(
        "INSERT INTO idempotency_key(tenant_id,doc_id,version) VALUES (%s,%s,%s)"
        " ON CONFLICT DO NOTHING", (t, d, e["version"])).rowcount == 0
    if seen:
        return bump(conn, "duplicate")
    floor = conn.execute("SELECT floor_version FROM tombstone WHERE tenant_id=%s AND doc_id=%s",
                         (t, d)).fetchone()
    if floor and e.get("version_seq") is not None and e["version_seq"] <= floor[0]:
        return bump(conn, "below_tombstone")
    stored = conn.execute("SELECT version_seq, modified_at, content_hash FROM pointer"
                          " WHERE tenant_id=%s AND uri=%s", (t, e["uri"])).fetchone()
    stored = dict(zip(("version_seq", "modified_at", "content_hash"), stored)) if stored else None
    # the pointer write repeats this compare, so a race here cannot lose an update
    return "apply" if newer(e, stored) else bump(conn, "stale")

def bump(conn, reason):
    conn.execute("INSERT INTO drop_counter(day,reason,n) VALUES (current_date,%s,1)"
                 " ON CONFLICT (day,reason) DO UPDATE SET n = drop_counter.n + 1", (reason,))
    return reason

