import math, time

W_R, W_S, W_P = 0.5, 0.3, 0.2
LN101 = math.log(101)

def score(item, now):
    age_days = (now - item["modified_at"]) / 86400
    return (W_R * math.exp(-age_days / 30)
            + W_S * min(1.0, math.log1p(item.get("shared_count", 0)) / LN101)
            + W_P * min(1.0, math.log1p(item.get("view_count", 0)) / LN101))

class TokenBucket:
    def __init__(self, per_hour):
        self.rate, self.tokens, self.t = per_hour / 3600.0, 1.0, time.monotonic()
    def take(self):
        while True:
            now = time.monotonic()
            self.tokens = min(5.0, self.tokens + (now - self.t) * self.rate)
            self.t = now
            if self.tokens >= 1:
                self.tokens -= 1
                return
            time.sleep((1 - self.tokens) / self.rate)

def crawl(conn, bus, lister, tenant, app, stream, quota_per_hour):
    bucket = TokenBucket(quota_per_hour * 0.5)  # stay at or under half the quota
    token = load_page_token(conn, tenant, app, stream)
    while True:
        bucket.take()
        page = lister(token)
        now = time.time()
        for it in page["items"]:
            save_frontier(conn, tenant, app, stream, it["object_id"], score(it, now))
        # send the best queued items now, so search works before the crawl ends
        for row in pop_best(conn, tenant, app, stream, limit=100):
            bus.publish(row.envelope, lane="backfill")
        token = page.get("next")
        commit_watermark(conn, tenant, app, stream, token)  # restart resumes here
        if not token:
            return

