def commit_batch(conn, tenant, app, stream, epoch, new_cursor, watermark, events):
    with conn.transaction():
        cur = conn.execute(
            "UPDATE stream_cursor SET cursor=pgp_sym_encrypt(%s, %s), watermark=%s, updated_at=now()"
            " WHERE tenant_id=%s AND app=%s AND stream=%s AND epoch=%s",
            (new_cursor, KEY, watermark, tenant, app, stream, epoch))
        if cur.rowcount == 0:
            return False  # fenced: someone took over with a higher epoch
        for ev in events:
            conn.execute("INSERT INTO outbox(tenant_id, envelope) VALUES (%s,%s)",
                         (tenant, Jsonb(ev)))
    return True

def take_over(conn, tenant, app, stream):
    row = conn.execute(
        "UPDATE stream_cursor SET epoch = epoch + 1 WHERE tenant_id=%s AND app=%s AND stream=%s"
        " RETURNING epoch", (tenant, app, stream)).fetchone()
    return row[0]

def relay_outbox(conn, bus, limit=500):
    with conn.transaction():
        rows = conn.execute("SELECT id, envelope FROM outbox WHERE sent_at IS NULL"
                            " ORDER BY id LIMIT %s FOR UPDATE SKIP LOCKED", (limit,)).fetchall()
        for oid, env in rows:
            bus.publish(env)  # at-least-once: a crash here re-sends, ch_dedupe drops the repeat
        if rows:
            conn.execute("UPDATE outbox SET sent_at=now() WHERE id = ANY(%s)", ([r[0] for r in rows],))
    return len(rows)

def lag_seconds(conn, tenant, app, stream):
    return conn.execute("SELECT EXTRACT(EPOCH FROM now() - watermark) FROM stream_cursor"
                        " WHERE tenant_id=%s AND app=%s AND stream=%s", (tenant, app, stream)).fetchone()[0]
